import{_ as t,a as r,b as i}from"./chunks/bubbles-03.CRJ58gUA.js";import{_ as e,o,c as n,a3 as s}from"./chunks/framework.D1iekJsc.js";const f=JSON.parse('{"title":"氣泡與輸入框","description":"MiniTavern 聊天氣泡和輸入框樣式：跟隨主題，或單獨改背景、圓角、旁白／動作／說話顏色和模糊。","frontmatter":{"title":"氣泡與輸入框","description":"MiniTavern 聊天氣泡和輸入框樣式：跟隨主題，或單獨改背景、圓角、旁白／動作／說話顏色和模糊。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"氣泡與輸入框 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"MiniTavern 聊天氣泡和輸入框樣式：跟隨主題，或單獨改背景、圓角、旁白／動作／說話顏色和模糊。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/manual/bubbles"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/manual/bubbles"}]]},"headers":[],"relativePath":"zh-TW/manual/bubbles.md","filePath":"zh-TW/manual/bubbles.md","lastUpdated":1791862671000}'),l={name:"zh-TW/manual/bubbles.md"};function g(c,a,h,p,u,d){return o(),n("div",null,[...a[0]||(a[0]=[s('<h1 id="氣泡與輸入框" tabindex="-1">氣泡與輸入框 <a class="header-anchor" href="#氣泡與輸入框" aria-label="Permalink to &quot;氣泡與輸入框&quot;">​</a></h1><p>路徑：底部 <strong>設定</strong> → <strong>聊天設置</strong> → <strong>氣泡與輸入框</strong>。</p><p>這裡改的是全域聊天外觀。主題和字號仍在 <strong>設定 → 主題和字體</strong>。</p><h2 id="步驟" tabindex="-1">步驟 <a class="header-anchor" href="#步驟" aria-label="Permalink to &quot;步驟&quot;">​</a></h2><div class="shot-flow"><figure class="shot-step"><img src="'+t+'" alt="設定首頁"><figcaption>1 · 設定 → 聊天設置</figcaption></figure><figure class="shot-step"><img src="'+r+'" alt="聊天設置裡的氣泡與輸入框"><figcaption>2 · 氣泡與輸入框</figcaption></figure><figure class="shot-step"><img src="'+i+'" alt="氣泡顏色和圓角"><figcaption>3 · 關掉跟隨主題後改樣式</figcaption></figure></div><h2 id="氣泡" tabindex="-1">氣泡 <a class="header-anchor" href="#氣泡" aria-label="Permalink to &quot;氣泡&quot;">​</a></h2><p><strong>氣泡</strong>和 <strong>輸入框</strong> 各有一個 <strong>跟隨主題</strong>。打開時用目前主題。關掉之後，下面的配置會蓋過主題；沒填的顏色仍用主題。</p><ol><li><strong>AI 氣泡背景</strong>、<strong>用戶氣泡背景</strong>：點進去是色環調色板。預設色是圓形，選中會打勾。可以改不透明度和顏色值，顏色值也能複製。一行上寫著「使用主題顏色」時，這一項仍跟主題。</li><li><strong>圓角</strong>：數值越大角越圓。拖動之後用這裡的數值，不再跟著主題間距縮放。</li><li>文字可以分開上色： <ul><li><strong>旁白文字</strong>、<strong>旁白背景</strong>：普通正文和加粗</li><li><strong>動作</strong>：<code>*星號*</code> 括起來的字</li><li><strong>說話</strong>：引號裡的字</li><li><strong>內心戲</strong></li></ul></li><li>角色卡如果不是用這套記號寫的，那些字仍會顯示，只是走旁白樣式。完整 HTML 卡片用自己的顏色，不靠這幾項。</li></ol><h2 id="輸入框" tabindex="-1">輸入框 <a class="header-anchor" href="#輸入框" aria-label="Permalink to &quot;輸入框&quot;">​</a></h2><p>關掉輸入框自己的 <strong>跟隨主題</strong> 之後，可以改背景、圓角、佔位符顏色、文字顏色、按鈕圖示顏色，以及 <strong>模糊</strong>。</p><p>模糊打開後可以調色調和強度。不支援模糊的 Android（API 31 以下）沒有這個開關。iOS 在關掉跟隨後，模糊默認是開的。</p><h2 id="預覽" tabindex="-1">預覽 <a class="header-anchor" href="#預覽" aria-label="Permalink to &quot;預覽&quot;">​</a></h2><p>右上角 <strong>預覽</strong> 打開示例頁：背景是目前語言的女性示例卡，下面有一段示例對話和輸入框。最後一條是 AI 訊息，帶繼續、智能回覆等按鈕，但點了不會發送。輸入框也不能發送。左側按鈕和右上角設定同樣點不了。</p><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./chat">聊天</a>：氣泡選單、會話裡的聊天設置</li><li><a href="./settings">設定與其它</a>：主題和字體</li></ul>',15)])])}const _=e(l,[["render",g]]);export{f as __pageData,_ as default};
